def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """

    import functools

    def _wrapper(f):
        @functools.wraps(f)
        def _wrapped(*args, **kwargs):
            if maxsize == 0:
                # Overflow
                return f(*args, **kwargs)
            key = functools.partial(f, *args, **kwargs)
            try:
                value = cache[key]
            except KeyError:
                # Miss
                value = f(*args, **kwargs)
                cache[key] = value
                # Add key to the MRU end of the list
                if len(cache) == maxsize:
                    # Bump key to the end
                    cache.move_to_end(key)
            else:
                # Hit
                # Move key to the MRU end of the list
                cache.move_to_end(key)
            return value

        # Create LRU cache
        cache = dict()

        return _wrapped

    return _wrapper

def lfu_cache(maxsize=128, typed=False):
    cache = {}

    def cache_wrapper(func):
        def wrapper(*args, **kwargs):
            key = args
            if kwargs:
                key += tuple(kwargs.items())
            if typed:
                key = (key, tuple([type(a) for a in args]) + tuple(type(v) for v in kwargs.values()))
            if key not in cache:
                cache[key] = func(*args, **kwargs)
            else:
                cache[key] = cache[key].lfu_count += 1
            if len(cache) > maxsize:
                min_count = min(cache.values())
                keys_to_delete = [k for k, c in cache.items() if c == min_count]
                for k in keys_to_delete:
                    del cache[k]
            return cache[key]
        return wrapper
    return cache_wrapper

