def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved.

    Orderings are constrained in such a way that if an object appears in two or more orderings, then the suffix that begins with the object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']
    """
    merged = set()
    for ordering in orderings:
        for obj in ordering:
            if obj not in merged:
                for suffix in ordering[ordering.index(obj):]:
                    if suffix not in merged:
                        merged.add(suffix)
    return list(merged)

