def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """

    result = {}
    # Make a copy of d1 to avoid unexpected mutations to be performed on the input dicts
    # If deepcopy is not used, changes to the original dicts will also affect the returned dict
    for key, value in copy.deepcopy(d1).items():
        if key not in d2:
            result[key] = value
        elif isinstance(value, collections.Mapping) and isinstance(d2.get(key), collections.Mapping):
            if level == 0:
                result[key] = value
            elif level > 0:
                result[key] = difference(value, d2[key], level - 1)
    return result

def _validate_labels(labels):
    """
    Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    messages = []
    for key, value in labels.items():
        if re.fullmatch(LABEL_KEY_REGEX, key) is None:
            messages.append(
                {"key": key,
                 "message": f"Label key '{key}' does not match the regex {LABEL_KEY_REGEX}"}
            )
        if re.fullmatch(LABEL_VALUE_REGEX, value) is None:
            messages.append(
                {"key": value,
                 "message": f"Label value '{value}' does not match the regex {LABEL_VALUE_REGEX}"}
            )
    if messages:
        raise ValidationError.from_raw_exceptions(messages)

def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    :param sql: The SQL query.
    :type sql: str or bytes
    :param params: The set of in-style parameters.
    :type params: dict or list
    :return: The formatted SQL query and the converted out-style parameters.
    :rtype: tuple
    """
    if self.in_style == SQLParams.NONE:
        raise ValueError("No parameters set")

    if self.in_style == SQLParams.NAMED:
        if not isinstance(params, dict):
            raise ValueError("Expected dict as parameter")
        formatted_params = {f":{key}": value for key, value in params.items()}
        sql = sql % formatted_params
    elif self.in_style == SQLParams.ORDINAL:
        if not isinstance(params, list):
            raise ValueError("Expected list as parameter")
        formatted_params = {index: value for index, value in enumerate(params, start=1)}
        sql = sql % formatted_params
    else:
        raise ValueError(f"Invalid parameter style: {self.in_style}")

    return sql, formatted_params

