def next_version(version):
    version_prefix = 'v'
    version_pattern = r'(\d+)(\.(\d+))?(\.(\d+))?'

    if version_prefix in version:
        version = version.lstrip(version_prefix)

    match = re.search(version_pattern, version)
    if match:
        major = match.group(1)
        minor = match.group(3)
        patch = match.group(5)

        if minor is not None:
            return f'{version_prefix}{major}.{int(minor) + 1}.0'
        elif patch is not None:
            return f'{version_prefix}{major}.{int(patch) + 1}'
        else:
            return f'{version_prefix}{int(major) + 1}.0.0'
    else:
        raise ValueError('Invalid version format')

