import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: A string or a list of strings containing the commands to run.
    :param args: A list of command-line arguments to pass to the program.
    :param cwd: The current working directory.
    :param verbose: Whether to enable verbose mode.
    :param hide_stderr: Whether to hide the stderr output.
    :param env: A dictionary of environment variables to pass to the program.
    """
    if isinstance(commands, str):
        commands = [commands]

    # Prepare the command string
    command_str = ' '.join(commands).format(*args)

    # Prepare the arguments for the subprocess
    if env is not None:
        env = {k: str(v) for k, v in env.items()}
    else:
        env = {}
    stdout = None
    stdin = None
    stderr = None
    if hide_stderr:
        stderr = subprocess.DEVNULL
    if verbose:
        stdout = subprocess.PIPE
    if cwd is not None:
        cwd = str(cwd)
    else:
        cwd = None

    # Run the command
    process = subprocess.Popen(command_str, shell=True, cwd=cwd, env=env, stdout=stdout, stdin=stdin, stderr=stderr)

    # Check the return code
    ret_code = process.returncode
    if ret_code != 0:
        raise Exception("Command failed with error code: {}".format(ret_code))

    # Return the output
    if stdout is not None and stdout != subprocess.PIPE:
        return stdout.getvalue()
    return None

