def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not iface:
        return True
    if not candidate:
        return False
    for attribute, expected in iface.items():
        if attribute in candidate:
            real = candidate[attribute]
            if isinstance(expected, list):
                if not isinstance(real, list):
                    return False
                for e in expected:
                    if e not in real:
                        return False
                return True
            if real != expected:
                return False
        elif tentative:
            # If the attribute is not present in the candidate, it is
            # considered as a tentative attribute
            return True
    return True

