def parse_diaspora_webfinger(document: str) -> Dict:
    try:
        # Try to parse the webfinger as a JSON document
        data = json.loads(document)
        return {
            "hcard_url": data["links"][0]["href"],
            "as_a_atom_entry": data["links"][1]["rel"] == "as_a_atom_entry"
        }
    except ValueError:
        # If the JSON document is not valid, parse the webfinger as an XRD document
        parse = xml.parsers.expat.ParserCreate()
        parse.StartElementHandler = lambda tag, attrs: data[tag] = attrs
        parse.EndElementHandler = lambda tag, attrs: None
        parse.CharacterDataHandler = lambda char: data[tag].append(char)
        parse.Parse(document)
        return {
            "hcard_url": data["links"][0]["href"],
            "as_a_atom_entry": data["links"][1]["rel"] == "as_a_atom_entry"
        }

