        for arg_name, value in values_dict.items():
            if value is not None:
                if arg_name == "debug":
                    values_dict[arg_name] = bool(int(value))
                elif arg_name == "memory":
                    values_dict[arg_name] = int(value)
                elif arg_name == "cpus":
                    values_dict[arg_name] = int(value)
                elif arg_name == "net":
                    values_dict[arg_name] = bool(int(value))
                else:
                    values_dict[arg_name] = value

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if 'CONFIG_PATH' not in os.environ:
        os.environ['CONFIG_PATH'] = self.config_path
